package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.ByteArrayOutputStream;
import java.io.File;
import java.io.IOException;
import java.io.OutputStream;
import java.math.*;
import java.util.*;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.apache.commons.compress.archivers.ArchiveOutputStream;
import org.apache.commons.compress.archivers.tar.TarArchiveEntry;
import org.apache.commons.compress.archivers.tar.TarArchiveOutputStream;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for TarArchiveOutputStream#finish().
 */
public class TarArchiveOutputStream_finish_TriageGen0Test {

    @Test
    public void testFinishWritesEOFRecords() throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        try (TarArchiveOutputStream taos = new TarArchiveOutputStream(baos)) {
            // Create a dummy entry to ensure state is valid
            TarArchiveEntry entry = new TarArchiveEntry("test.txt");
            taos.putArchiveEntry(entry);
            taos.write("content".getBytes());
            taos.closeArchiveEntry();

            // Execute finish
            taos.finish();
        }

        // Tar files end with two zero blocks (EOF records).
        // Each block is blockSize (default 512).
        // Since we can't easily verify the exact internal byte content of EOF without 
        // deep inspection, we verify that the stream was written to and is not empty.
        Assert.assertTrue("Output stream should not be empty after finish", baos.size() > 0);
    }

    @Test
    public void testFinishAfterCloseThrowsException() throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        TarArchiveOutputStream taos = new TarArchiveOutputStream(baos);

        taos.close();

        try {
            taos.finish();
            Assert.fail("Expected IOException when calling finish on a closed stream");
        } catch (IOException e) {
            // Success: IOException expected
        }
    }

    @Test
    public void testFinishMultipleTimesThrowsException() throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        try (TarArchiveOutputStream taos = new TarArchiveOutputStream(baos)) {
            taos.finish();

            // Calling finish a second time should typically cause an IOException 
            // because the underlying stream or state is finalized.
            try {
                taos.finish();
                // Depending on implementation, it might throw or just be a no-op.
                // In Apache Commons Compress, calling finish/close twice usually triggers errors.
            } catch (IOException e) {
                // Expected
            }
        }
    }
}
